X = [[Int(f'x_{i}_{j}') for j in range(10)] for i in range(10)]
s=Solver()
for i in range(10):
    for j in range(10): s.add(X[i][j]>=0, X[i][j]<=9)
for i in range(10): s.add(Distinct(X[i]))
for j in range(10): s.add(Distinct([X[i][j] for i in range(10)]))
for idx,v in enumerate(clues):
    if v!=-1: s.add(X[idx//10][idx%10]==v)
# maybe add symmetry? no
print(s.check())
if s.check()==sat:
    m=s.model()
    sol=[m.evaluate(X[i][j]).as_long() for i in range(10) for j in range(10)]
    for i in range(10): print(sol[10*i:10*i+10])
    print(sol)
